package kr.tong.sky;

import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.time.*;
import java.nio.file.*;

public class RouteRulesTest {
 static final LocalDate TODAY=LocalDate.of(2026,10,31),OZ_LIMIT=TODAY.plusDays(359),HISTORICAL_NETWORK_LIMIT=LocalDate.of(2026,12,17);
 JSONObject catalog(boolean oz)throws Exception{return new JSONObject(Files.readString(Path.of(System.getProperty("tongsky.assets","tong-sky-121/tong-sky/src/main/assets"),oz?"asiana-regions.json":"regions.json")));}
 JSONObject q(String origin,String destination,String month)throws Exception{return new JSONObject().put("origin",origin).put("destination",destination).put("month",month);}
 boolean allowed(String carrier,String origin,String destination)throws Exception{return RouteRules.allowed(carrier,q(origin,destination,"2026-11"),TODAY,"OZ".equals(carrier)?OZ_LIMIT:HISTORICAL_NETWORK_LIMIT);}
 JSONObject config(String... ozRegions)throws Exception{JSONArray selected=new JSONArray();for(String r:ozRegions)selected.put(r);return new JSONObject().put("enabled",true).put("hour",9).put("minute",10).put("origin","ICN").put("KE",new JSONArray()).put("OZ",selected);}
 int count(JSONArray batches)throws Exception{int out=0;for(int i=0;i<batches.length();i++)out+=batches.getJSONObject(i).getJSONArray("queries").length();return out;}

 @Test public void october31AsianaAllRegionsSkip364UnsupportedQueryUnits()throws Exception{
  JSONArray names=new JSONArray();for(String name:ScanSchedule.REGIONS)names.put(name);JSONObject cfg=config();cfg.put("OZ",names);JSONArray batches=ScanSchedule.batches(cfg,catalog(false),catalog(true),TODAY,1000);
  assertEquals(1274,count(batches));assertEquals(6,batches.length());for(int i=0;i<batches.length();i++){JSONObject b=batches.getJSONObject(i);assertTrue(b.getString("key").startsWith("OZ-ICN-"));assertEquals("OZ",b.getString("carrier"));for(int j=0;j<b.getJSONArray("queries").length();j++)assertEquals("OZ",b.getJSONArray("queries").getJSONObject(j).getString("carrier"));}
 }
 @Test public void asianaEuropePrunesOnlyBudapest()throws Exception{JSONArray batches=ScanSchedule.batches(config("유럽"),catalog(false),catalog(true),TODAY,1000);assertEquals(208,count(batches));assertEquals(1,batches.length());}
 @Test public void explicitUnservedCitiesAreNotReusedForOtherOriginPairs()throws Exception{for(String d:new String[]{"BUD","CKG","DAD","SEA","ALA","TAS"}){assertFalse(allowed("OZ","ICN",d));assertFalse(allowed("OZ",d,"LAX"));}}
 @Test public void unsupportedIcnPairsAreSymmetricButNotGlobalAirportDeletions()throws Exception{for(String d:new String[]{"GMP","CJU","CJJ","KWJ","TAE","RSU","SHA"}){assertFalse(allowed("OZ","ICN",d));assertFalse(allowed("OZ",d,"ICN"));}assertTrue(allowed("OZ","GMP","SHA"));assertTrue(allowed("OZ","SHA","GMP"));assertTrue(allowed("OZ","GMP","CJU"));assertTrue(allowed("OZ","CJU","GMP"));}
 @Test public void uncertainAsianaChiangMaiAndConfirmedKoreanAirWinterRoutesRemainEligible()throws Exception{assertTrue(allowed("OZ","ICN","CNX"));assertTrue(allowed("KE","ICN","OIT"));assertTrue(allowed("KE","ICN","UKB"));}
 @Test public void asianaRestrictionsDoNotRemoveSupportedKoreanAirService()throws Exception{for(String d:new String[]{"BUD","DAD","SEA"})assertTrue(allowed("KE","ICN",d));}
 @Test public void historicalKoreanAirIcnWindowSkips210UnsupportedQueryUnits()throws Exception{JSONObject catalog=catalog(false);java.util.Set<String> keys=new java.util.HashSet<>();java.util.Iterator<String> names=catalog.getJSONObject("regions").keys();while(names.hasNext()){JSONArray queries=RegionBatch.create("ICN",names.next(),catalog,TODAY,1000,HISTORICAL_NETWORK_LIMIT).getJSONArray("queries");for(int i=0;i<queries.length();i++)keys.add(Search.key(queries.getJSONObject(i)));}assertEquals(528,keys.size());}
 @Test public void currentKoreanAirIcnNetworkRestrictionsAreSymmetricAndPairSpecific()throws Exception{for(String d:new String[]{"ZRH","KKJ","NGB","TAK","SHI","SHA","URC","WUX","WEH","ISG","HIJ","TAG","BKI","CMB","CRK","MEL","SVO","VVO","LED","ALA","IKT","DXB","TLV","GMP","PUS","CJU","KWJ","KUV","TAE","RSU","USN","WJU","HIN","CJJ","KPO"}){assertFalse(d,allowed("KE","ICN",d));assertFalse(d,allowed("KE",d,"ICN"));}assertTrue(allowed("KE","GMP","SHA"));assertTrue(allowed("KE","GMP","CJU"));assertTrue(allowed("KE","PUS","CJU"));assertTrue(allowed("KE","TAE","CJU"));}
 @Test public void koreanAirCurrentNetworkSnapshotDoesNotBecomeAPermanentBlacklist()throws Exception{assertTrue(RouteRules.allowed("KE",q("ICN","SVO","2026-11"),LocalDate.of(2026,10,29),HISTORICAL_NETWORK_LIMIT));assertTrue(RouteRules.allowed("KE",q("ICN","SVO","2026-12"),TODAY,LocalDate.of(2026,12,18)));assertTrue(RouteRules.allowed("KE",q("ICN","ALA","2027-01"),TODAY,LocalDate.of(2027,1,31)));assertFalse(RouteRules.allowed("KE",q("ICN","SVO","2027-01"),LocalDate.of(2027,1,1),LocalDate.of(2027,1,31)));assertTrue(RouteRules.allowed("KE",q("ICN","ZRH","2027-04"),LocalDate.of(2026,11,3),LocalDate.of(2027,4,30)));}
 @Test public void koreanAirHiroshimaIsExcludedOnlyBeforeItsFirstServiceDate()throws Exception{
  JSONObject dec=q("ICN","HIJ","2026-12"),nov=q("HIJ","ICN","2026-11");assertFalse(RouteRules.allowed("KE",dec,TODAY,HISTORICAL_NETWORK_LIMIT));assertFalse(RouteRules.allowed("KE",dec,TODAY,LocalDate.of(2026,12,22)));assertTrue(RouteRules.allowed("KE",dec,TODAY,LocalDate.of(2026,12,23)));assertFalse(RouteRules.allowed("KE",nov,TODAY,LocalDate.of(2027,1,31)));assertTrue(RouteRules.allowed("KE",q("HIJ","ICN","2027-01"),TODAY,LocalDate.of(2027,1,31)));assertTrue(allowed("OZ","ICN","HIJ"));
 }
 @Test public void emptyRegionDoesNotBecomeAPhantomQueryOrScheduleBatch()throws Exception{
  JSONObject empty=RegionBatch.create("ICN","대한민국",catalog(true),TODAY,1000,OZ_LIMIT,"OZ");assertEquals(0,empty.getJSONArray("queries").length());assertTrue(RegionBatch.complete(empty));JSONArray batches=ScanSchedule.batches(config("대한민국","유럽"),catalog(false),catalog(true),TODAY,1000);assertEquals(1,batches.length());assertEquals("유럽",batches.getJSONObject(0).getString("region"));assertEquals(208,count(batches));
 }
 @Test public void allEmptySelectedRegionsExplainThatThereIsNothingEligible()throws Exception{try{ScanSchedule.batches(config("대한민국","중동/아프리카"),catalog(false),catalog(true),TODAY,1000);fail();}catch(Exception e){assertTrue(e.getMessage().contains("현재 조회 가능한 노선이 없습니다"));}}
 @Test public void oldBatchFilteringPreservesOrderAndMapsTheCompletedCursor()throws Exception{
  JSONArray qs=new JSONArray().put(q("ICN","CDG","2026-11")).put(q("ICN","BUD","2026-11")).put(q("FCO","ICN","2026-11")).put(q("ICN","SEA","2026-11")).put(q("ICN","LAX","2026-11"));JSONObject old=new JSONObject().put("key","OZ-ICN-유럽").put("carrier","OZ").put("cursor",3).put("failures",3).put("completedAt",99).put("queries",qs);
  JSONObject kept=RouteRules.filterBatch(old,"OZ",TODAY,OZ_LIMIT);assertEquals("OZ-ICN-유럽",kept.getString("key"));assertEquals(3,kept.getJSONArray("queries").length());assertEquals("ICN-CDG-2026-11",Search.key(kept.getJSONArray("queries").getJSONObject(0)));assertEquals("FCO-ICN-2026-11",Search.key(kept.getJSONArray("queries").getJSONObject(1)));assertEquals("ICN-LAX-2026-11",Search.key(kept.getJSONArray("queries").getJSONObject(2)));assertEquals(2,kept.getInt("cursor"));assertEquals(2,kept.getInt("failures"));assertEquals(0,kept.getLong("completedAt"));assertEquals(5,old.getJSONArray("queries").length());assertEquals(3,old.getInt("cursor"));assertFalse(old.getJSONArray("queries").getJSONObject(0).has("carrier"));
 }
 @Test public void completedOldBatchRetainsItsOriginalCompletionClock()throws Exception{JSONObject old=new JSONObject().put("cursor",2).put("completedAt",100).put("queries",new JSONArray().put(q("ICN","BUD","2026-11")).put(q("ICN","CDG","2026-11")));JSONObject kept=RouteRules.filterBatch(old,"OZ",TODAY,OZ_LIMIT);assertEquals(1,kept.getInt("cursor"));assertEquals(100,kept.getLong("completedAt"));assertEquals(1,kept.getJSONArray("queries").length());}
 @Test public void stalePastOrBeyondLimitMonthsAreRemovedFromQueuedBatches()throws Exception{JSONObject old=new JSONObject().put("cursor",0).put("queries",new JSONArray().put(q("ICN","CDG","2026-09")).put(q("ICN","CDG","2026-11")).put(q("ICN","CDG","2027-01")));JSONObject kept=RouteRules.filterBatch(old,"KE",TODAY,HISTORICAL_NETWORK_LIMIT);assertEquals(1,kept.getJSONArray("queries").length());assertEquals("2026-11",kept.getJSONArray("queries").getJSONObject(0).getString("month"));}
 @Test public void wrongCarrierBatchAndQueryAreRejected()throws Exception{JSONObject batch=new JSONObject().put("carrier","KE").put("queries",new JSONArray().put(q("ICN","CDG","2026-11")));try{RouteRules.filterBatch(batch,"OZ",TODAY,OZ_LIMIT);fail();}catch(Exception e){assertTrue(e.getMessage().contains("항공사"));}batch.put("carrier","OZ").put("queries",new JSONArray().put(q("ICN","CDG","2026-11").put("carrier","KE")));try{RouteRules.filterBatch(batch,"OZ",TODAY,OZ_LIMIT);fail();}catch(Exception e){assertTrue(e.getMessage().contains("항공사"));}}
 @Test public void savedCalendarQueriesStayReadableWhileNewCollectionIsExcluded()throws Exception{JSONObject search=new JSONObject().put("carrier","OZ").put("origin","ICN").put("destination","BUD").put("start",Search.today().toString()).put("end",Search.today().toString()).put("round",false);assertFalse(Search.queries(search).isEmpty());assertTrue(Search.collectionQueries(search).isEmpty());}
 @Test public void watchCollectionPreservesActualCarrierAndSupportedDomesticPairs()throws Exception{JSONObject search=new JSONObject().put("carrier","OZ").put("origin","GMP").put("destination","CJU").put("round",true);assertFalse(Search.collectionQueries(search).isEmpty());for(JSONObject q:Search.collectionQueries(search))assertEquals("OZ",q.getString("carrier"));search.put("carrier","KE").put("origin","ICN").put("destination","BUD");assertFalse(Search.collectionQueries(search).isEmpty());for(JSONObject q:Search.collectionQueries(search))assertEquals("KE",q.getString("carrier"));}
 @Test public void manualAsianaCollectionUsesTheSameNetworkRules()throws Exception{String month=YearMonth.from(Search.today()).toString();assertEquals(0,AsianaData.plan("ICN","BUD",month,true,true).length());assertEquals(0,AsianaData.plan("ICN","SHA",month,false,true).length());assertEquals(2,AsianaData.plan("GMP","SHA",month,false,true).length());assertEquals(2,AsianaData.plan("GMP","CJU",month,false,true).length());}
 @Test public void hnlSuspensionStartsInJulyAndLeavesJuneEligibleInBothDirections()throws Exception{
  LocalDate today=LocalDate.of(2026,6,1),limit=LocalDate.of(2026,8,31);for(String[] pair:new String[][]{{"ICN","HNL"},{"HNL","ICN"}}){assertTrue(RouteRules.allowed("OZ",q(pair[0],pair[1],"2026-06"),today,limit));assertFalse(RouteRules.allowed("OZ",q(pair[0],pair[1],"2026-07"),today,limit));assertEquals("공식 운항 중단(2026-07-01~)",RouteRules.reason("OZ",q(pair[0],pair[1],"2026-07"),today,limit));}
 }
 @Test public void hnlSuspensionDoesNotBecomeAGlobalAirportOrOtherCarrierExclusion()throws Exception{
  for(String[] pair:new String[][]{{"ICN","HNL"},{"HNL","ICN"}}){assertFalse(allowed("OZ",pair[0],pair[1]));assertTrue(allowed("KE",pair[0],pair[1]));}for(String[] pair:new String[][]{{"LAX","HNL"},{"HNL","LAX"},{"GMP","HNL"},{"HNL","GMP"}})assertTrue(allowed("OZ",pair[0],pair[1]));
 }
 @Test public void everyReportedDecemberThroughAprilHnlQueryIsExcluded()throws Exception{
  LocalDate today=LocalDate.of(2026,11,2),limit=Search.lastDate(true,today);for(YearMonth month=YearMonth.of(2026,12);!month.isAfter(YearMonth.of(2027,4));month=month.plusMonths(1))for(String[] pair:new String[][]{{"ICN","HNL"},{"HNL","ICN"}})assertFalse(month+" "+pair[0]+"-"+pair[1],RouteRules.allowed("OZ",q(pair[0],pair[1],month.toString()),today,limit));
 }
 @Test public void november2AmericasAndFullPlansRemoveOnlyThe24HnlQueryUnits()throws Exception{
  LocalDate today=LocalDate.of(2026,11,2);JSONArray americas=ScanSchedule.batches(config("미주"),catalog(false),catalog(true),today,1000);assertEquals(72,count(americas));java.util.Set<String> destinations=new java.util.HashSet<>();JSONArray queries=americas.getJSONObject(0).getJSONArray("queries");for(int i=0;i<queries.length();i++){JSONObject query=queries.getJSONObject(i);destinations.add("ICN".equals(query.getString("origin"))?query.getString("destination"):query.getString("origin"));}assertEquals(java.util.Set.of("LAX","JFK","SFO"),destinations);
  JSONArray names=new JSONArray();for(String name:ScanSchedule.REGIONS)names.put(name);assertEquals(1176,count(ScanSchedule.batches(config().put("OZ",names),catalog(false),catalog(true),today,1000)));
 }
 @Test public void suspendedHnlQueueItemsAreFilteredWithTheCursorMappedAndOriginalUntouched()throws Exception{
  JSONArray queries=new JSONArray().put(q("ICN","HNL","2026-12")).put(q("ICN","LAX","2026-12")).put(q("HNL","ICN","2027-01")).put(q("JFK","ICN","2027-01")).put(q("ICN","SFO","2027-02"));JSONObject old=new JSONObject().put("carrier","OZ").put("key","OZ-ICN-미주").put("queries",queries).put("cursor",3).put("failures",2).put("completedAt",99).put("error","existing diagnostic");String before=old.toString();JSONObject filtered=RouteRules.filterBatch(old,"OZ",LocalDate.of(2026,11,2),Search.lastDate(true,LocalDate.of(2026,11,2)));assertEquals(3,filtered.getJSONArray("queries").length());assertEquals("ICN-LAX-2026-12",Search.key(filtered.getJSONArray("queries").getJSONObject(0)));assertEquals("JFK-ICN-2027-01",Search.key(filtered.getJSONArray("queries").getJSONObject(1)));assertEquals("ICN-SFO-2027-02",Search.key(filtered.getJSONArray("queries").getJSONObject(2)));assertEquals(1,filtered.getInt("cursor"));assertEquals(1,filtered.getInt("failures"));assertEquals(0,filtered.getLong("completedAt"));assertEquals("existing diagnostic",filtered.getString("error"));assertEquals(before,old.toString());
 }
 @Test public void completedHnlQueueFilteringRetainsOriginalCompletionClock()throws Exception{
  JSONObject old=new JSONObject().put("carrier","OZ").put("cursor",3).put("completedAt",99).put("queries",new JSONArray().put(q("ICN","HNL","2026-12")).put(q("HNL","ICN","2026-12")).put(q("ICN","LAX","2026-12")));JSONObject filtered=RouteRules.filterBatch(old,"OZ",LocalDate.of(2026,11,2),Search.lastDate(true,LocalDate.of(2026,11,2)));assertEquals(1,filtered.getJSONArray("queries").length());assertEquals(1,filtered.getInt("cursor"));assertEquals(99,filtered.getLong("completedAt"));assertEquals(3,old.getJSONArray("queries").length());
 }
 @Test public void hnlSavedCalendarSearchAndCityRemainWhileNewCollectionIsExcluded()throws Exception{
  JSONObject search=new JSONObject().put("carrier","OZ").put("origin","ICN").put("destination","HNL").put("start",Search.today().toString()).put("end",Search.today().toString()).put("round",true).put("returnStart",Search.today().toString()).put("returnEnd",Search.today().toString());String before=search.toString();assertFalse(Search.queries(search).isEmpty());assertTrue(Search.collectionQueries(search).isEmpty());assertEquals(before,search.toString());assertEquals(0,AsianaData.plan("ICN","HNL",YearMonth.from(Search.today()).toString(),true,true).length());boolean retained=false;JSONArray cities=catalog(true).getJSONObject("regions").getJSONArray("미주");for(int i=0;i<cities.length();i++)retained|="HNL".equals(cities.getJSONObject(i).getString("code"));assertTrue(retained);
 }
}
